// spec: .qa/e2e/specs/match-mutual.md 1.4 · кейс .qa/tests/match-mutual/MATCH-04.md
import { randomUUID } from 'crypto';
import { test, expect } from '../../fixtures';
import { captureApi, myMatches, matchIdOf, fullMatchId, messageTextKey, restPost, restDelete, qaText, type Api } from '../_shared/api';
import { saveSession } from '../_shared/session';

test.describe('Взаимный матч (сервер)', () => {
  test('Сообщение без мэтча — в несуществующий и в чужой мэтч → 403 @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const reg1 = await asUser('reg1');
    const created: string[] = [];
    let a: Api | undefined;
    try {
      a = await captureApi(free);
      const r = await captureApi(reg1);
      // Колонка текста — из своего чата 2651ee46 (там есть сообщения QA-AUTO).
      const textKey = await messageTextKey(a, await fullMatchId(a, '2651ee46'));
      // Чужой мэтч: мэтч reg1, в котором нет free (reg1↔reg2 83f63177…).
      const foreign = (await myMatches(r)).filter((m) => !JSON.stringify(m).includes(a!.userId)).map(matchIdOf).find(Boolean);
      expect(foreign, 'у reg1 есть мэтч без free (reg1↔reg2)').toBeTruthy();

      for (const [name, matchId] of [['несуществующий', randomUUID()], ['чужой', foreign!]] as const) {
        const res = await restPost(a, 'messages', { match_id: matchId, sender_id: a.userId, [textKey]: qaText(`no-match ${name}`) });
        if (res.ok()) for (const row of await res.json()) created.push(String(row.id));
        expect(res.status(), `мэтч ${name}: ${await res.text()}`).toBe(403);
      }
    } finally {
      // Если сервер ошибочно принял сообщение — удалить его (QA-AUTO).
      if (a) for (const id of created) await restDelete(a, `messages?id=eq.${id}`).catch(() => {});
      await saveSession(free, 'free');
      await saveSession(reg1, 'reg1');
    }
  });
});
